import{_ as a,a as t,a3 as o,o as i}from"./chunks/framework.edeurCMZ.js";const u=JSON.parse('{"title":"Why @workspace matters in Copilot Chat","description":"","frontmatter":{},"headers":[],"relativePath":"devdoc/userdoc/copilot/UsingWorkspace.md","filePath":"devdoc/userdoc/copilot/UsingWorkspace.md","lastUpdated":1788274664000}'),l={name:"devdoc/userdoc/copilot/UsingWorkspace.md"};function s(n,e,c,r,p,d){return i(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="why-workspace-matters-in-copilot-chat" tabindex="-1">Why <code>@workspace</code> matters in Copilot Chat <a class="header-anchor" href="#why-workspace-matters-in-copilot-chat" aria-label="Permalink to &quot;Why `@workspace` matters in Copilot Chat&quot;">​</a></h1><p><code>@workspace</code> is a Copilot Chat context selector that enables Copilot to use files from your currently opened project as grounding context.</p><p>When you chat with a domain agent like the <code>@ecl</code> participant, it can be highly knowledgeable about ECL concepts, syntax, and documentation. But that does not automatically mean it can read your local files.</p><p>That is the key difference:</p><ul><li>Without <code>@workspace</code>: the agent answers from its built-in knowledge, documentation context, and tools, but not your local project files unless you paste content.</li><li>With <code>@workspace</code>: you explicitly grant access to your open workspace context, so Copilot can read referenced files and use nearby project structure as context.</li></ul><h2 id="what-this-looks-like-in-practice" tabindex="-1">What this looks like in practice <a class="header-anchor" href="#what-this-looks-like-in-practice" aria-label="Permalink to &quot;What this looks like in practice&quot;">​</a></h2><h3 id="example-1-no-workspace-context" tabindex="-1">Example 1 (no workspace context) <a class="header-anchor" href="#example-1-no-workspace-context" aria-label="Permalink to &quot;Example 1 (no workspace context)&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>@ecl explain #file:initfiles/examples/TutorialYourName/BWR_ProcessRawData.ecl in the context of initfiles/examples/TutorialYourName</span></span></code></pre></div><p>Typical result:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>“I can only answer questions about ECL based on the documentation and tools available to me. The file you referenced is a local workspace file that I don’t have access to view.”</span></span></code></pre></div><p>Why this happens:</p><ul><li>You asked for a local file explanation.</li><li>The agent was not given workspace scope.</li><li>So it could not open or inspect that file, even though your prompt referenced it.</li></ul><h3 id="example-2-workspace-context-enabled" tabindex="-1">Example 2 (workspace context enabled) <a class="header-anchor" href="#example-2-workspace-context-enabled" aria-label="Permalink to &quot;Example 2 (workspace context enabled)&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>@workspace @ecl explain #file:initfiles/examples/TutorialYourName/BWR_ProcessRawData.ecl in the context of initfiles/examples/TutorialYourName</span></span></code></pre></div><p>Typical result:</p><p>Now Copilot explains the file clearly and specifically.</p><h2 id="why-this-happens" tabindex="-1">Why this happens <a class="header-anchor" href="#why-this-happens" aria-label="Permalink to &quot;Why this happens&quot;">​</a></h2><ul><li><code>@workspace</code> tells Copilot to use your workspace as an allowed source of truth.</li><li>The <code>#file</code> reference can now be resolved to the actual file.</li><li>The agent can combine ECL knowledge with the real code in your project folder.</li></ul><h3 id="simple-mental-model" tabindex="-1">Simple mental model <a class="header-anchor" href="#simple-mental-model" aria-label="Permalink to &quot;Simple mental model&quot;">​</a></h3><p>Think of <code>@ecl</code> as the specialist and <code>@workspace</code> as the permission slip.</p><ul><li><code>@ecl</code> = “I know ECL.”</li><li><code>@workspace</code> = “You may read my project files.”</li><li>Together = “Explain my real ECL code, in my real repo context.”</li></ul><h3 id="when-to-add-workspace" tabindex="-1">When to add @workspace <a class="header-anchor" href="#when-to-add-workspace" aria-label="Permalink to &quot;When to add @workspace&quot;">​</a></h3><p>Use <code>@workspace</code> whenever your question depends on:</p><ul><li>A specific local file</li><li>Project-relative imports/includes</li><li>Folder-level conventions</li><li>Cross-file behavior in your repo</li></ul><p>If your question is purely conceptual (for example, “What is a SuperFile?”), <code>@workspace</code> is often unnecessary.</p><h3 id="practical-prompt-pattern" tabindex="-1">Practical prompt pattern <a class="header-anchor" href="#practical-prompt-pattern" aria-label="Permalink to &quot;Practical prompt pattern&quot;">​</a></h3><p>A reliable pattern is:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>@workspace @ecl explain #file:path/to/file.ecl in the context of path/to/folder</span></span></code></pre></div><p>This gives Copilot three things at once:</p><ul><li>Permission to read files</li><li>The exact file to inspect</li><li>The surrounding folder context to interpret intent</li></ul><h2 id="bottom-line" tabindex="-1">Bottom line <a class="header-anchor" href="#bottom-line" aria-label="Permalink to &quot;Bottom line&quot;">​</a></h2><p>Adding <code>@workspace</code> is what turns a general expert response into a code-aware explanation of your actual files. In the example above, that single addition is exactly why the second prompt works and the first one doesn&#39;t.</p>',32)])])}const m=a(l,[["render",s]]);export{u as __pageData,m as default};
